  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({
    premium: quotePremium((step as QuoteStep).items),
  }));
}

