import { describe, expect, it } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO claim office", () => {
  // --- Quote: simplest cases ---
  it("empty item list -> premium 5 G (processing fee only)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(results).toEqual([{ premium: 5 }]);
  });
  it("single plain sword (newcomer) -> premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] }],
    });

    expect(results).toEqual([{ premium: 115 }]);
  });
  it("single plain amulet (newcomer) -> premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] }],
    });

    expect(results).toEqual([{ premium: 71 }]);
  });
  it.todo("single plain staff (newcomer) -> premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("single plain potion (newcomer) -> premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Components and the block of 3 alike ---
  it.todo("2 runes -> base premium 50 G (no block)");
  it.todo("3 runes -> base premium 60 G (block applies)");
  it.todo("4 runes -> base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -> base premium 175 G (no block)");
  it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: alike means same type)");
  it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds 50 G surcharge (50 % of that item's base premium)");
  it.todo("sword with enchantment 5 adds 30 G high-enchantment surcharge (threshold is >= 5)");
  it.todo("sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 adds both surcharges (50 G + 30 G)");
  it.todo("cursed sword + plain amulet -> 210 G before policy modifiers and fee (curse applies to the cursed item only)");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");
  it.todo("first insurance surcharge applies to every quote, also for a long-standing customer's second contract");

  // --- Rounding ---
  it.todo("premium of 197.5 G rounds up to 198 G (MHPCO's favour)");
  it.todo("payout of 350.5 G rounds down to 350 G (MHPCO's favour)");
  it.todo("intermediate amounts stay fractional; only the final premium is rounded");

  // --- Claim: standard reimbursement ---
  it.todo("steel sword enchantment 3, damage 500 G -> payout 400 G (deductible only)");
  it.todo("rune (no enchantment, no material), damage 200 G -> payout 100 G (deductible only)");
  it.todo("damage below the 100 G deductible -> payout 0 G");

  // --- Claim: special clauses ---
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50 % clause, then deductible)");
  it.todo("dragon-material sword enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword enchantment 8, damage 1000 G -> payout 400 G (50 % clause wins, then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G (50 % clause wins over dragon material)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) -> payout 600 G (deductible per damaged item)");

  // --- Claim: insurance sum and cap ---
  it.todo("policy with a sword and an amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy with two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("cursed sword -> cap 2000 G based on the unmodified insurance value");
  it.todo("policy with a sword and 3 runes -> insurance sum 1750 G (block discount does not lower the sum)");
  it.todo("two successive 1500 G claims on a 1000 G sword -> payouts 1400 G then 600 G, remaining cap 600 G then 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("two sword damages against a policy covering two swords -> each damage has its own deductible");
  it.todo("more damages of a type than the policy covers -> throws an error (whole claim rejected)");

  // --- Error cases ---
  it.todo("quote with an unknown item type -> throws an error");
  it.todo("claim for an item not part of the policy -> throws an error");
  it.todo("claim damage with a negative amount -> throws an error");

  // --- Integration examples ---
  it.todo("newcomer with a cursed steel sword enchantment 3 -> premium 165 G");
  it.todo("long-standing customer's (3 years) second quote, cursed steel sword enchantment 7 -> premium 160 G");
  it.todo("schema example: 5-year customer, amulet quote then 200 G amulet claim -> premium and payout results");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes a results array to stdout");
  it.todo("CLI exits with a non-zero status and writes to stderr for an unknown item type");
});

